    i2c__TARGET_ID_t TARGET_ID;
    i2c__ACQDATA_t ACQDATA;
    i2c__TXDATA_t TXDATA;
    i2c__HOST_TIMEOUT_CTRL_t HOST_TIMEOUT_CTRL;
    i2c__TARGET_TIMEOUT_CTRL_t TARGET_TIMEOUT_CTRL;
    i2c__TARGET_NACK_COUNT_t TARGET_NACK_COUNT;
    i2c__TARGET_ACK_CTRL_t TARGET_ACK_CTRL;
    i2c__ACQ_FIFO_NEXT_DATA_t ACQ_FIFO_NEXT_DATA;
